<?php
namespace App\Http\Controllers\Api\V1;
use App\Models\{PosRegister,PosShift,PosReceipt,PosReceiptItem,PosReceiptPayment,ProductVariant}; use App\Services\{AuthorizationService,OptionalModuleService,StockMovementService}; use App\Support\{Decimal,TenantContext}; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use Illuminate\Support\Str; use Illuminate\Validation\ValidationException;
final class PosController {
 public function registers(Request $r,OptionalModuleService $modules){$modules->require('pos');return response()->json(['data'=>PosRegister::where('tenant_id',app(TenantContext::class)->id())->paginate(25)]);}
 public function storeRegister(Request $r,AuthorizationService $auth,OptionalModuleService $modules){$modules->require('pos');$t=app(TenantContext::class)->id();$d=$r->validate(['company_id'=>'required|uuid','branch_id'=>'nullable|uuid','location_id'=>'nullable|uuid','name'=>'required|string|max:100','code'=>'required|alpha_dash|max:30','payment_methods'=>'nullable|array']);abort_unless($auth->allows($r->user(),$t,'pos.manage',$d['company_id']),403);return response()->json(['data'=>PosRegister::create([...$d,'tenant_id'=>$t])],201);}
 public function openShift(Request $r,PosRegister $register,OptionalModuleService $modules,AuthorizationService $auth){$modules->require('pos');$t=app(TenantContext::class)->id();abort_unless($register->tenant_id===$t,404);abort_unless($auth->allows($r->user(),$t,'pos.manage',$register->company_id),403);abort_unless(!PosShift::where('register_id',$register->id)->where('state','open')->exists(),422,'The register already has an open shift.');$d=$r->validate(['opening_cash'=>'required|numeric|min:0']);return response()->json(['data'=>PosShift::create(['tenant_id'=>$t,'register_id'=>$register->id,'cashier_id'=>$r->user()->id,'opening_cash'=>$d['opening_cash'],'state'=>'open','opened_at'=>now()])],201);}
 public function sell(Request $r,PosRegister $register,StockMovementService $movements,OptionalModuleService $modules,AuthorizationService $auth){$modules->require('pos');$t=app(TenantContext::class)->id();abort_unless($register->tenant_id===$t,404);abort_unless($auth->allows($r->user(),$t,'pos.sell',$register->company_id),403);$d=$r->validate(['shift_id'=>'required|uuid','customer_id'=>'nullable|uuid','idempotency_key'=>'required|string|max:100','items'=>'required|array|min:1','items.*.variant_id'=>'required|uuid','items.*.quantity'=>'required|numeric|gt:0','items.*.unit_price'=>'required|numeric|min:0','items.*.tax_rate'=>'nullable|numeric|min:0','payments'=>'required|array|min:1','payments.*.method'=>'required|string|max:40','payments.*.amount'=>'required|numeric|gt:0']);$shift=PosShift::where('tenant_id',$t)->where('register_id',$register->id)->whereKey($d['shift_id'])->where('state','open')->firstOrFail();if($existing=PosReceipt::where('tenant_id',$t)->where('idempotency_key',$d['idempotency_key'])->first())return response()->json(['data'=>$existing]);$receipt=DB::transaction(function()use($d,$register,$shift,$r,$movements,$t){$subtotal='0';$tax='0';$lines=[];foreach($d['items'] as $line){$variant=ProductVariant::where('tenant_id',$t)->whereKey($line['variant_id'])->firstOrFail();$qty=Decimal::normalize((string)$line['quantity']);$price=Decimal::normalize((string)$line['unit_price']);$rate=Decimal::normalize((string)($line['tax_rate']??0));$sub=Decimal::mul($qty,$price);$taxAmount=Decimal::div(Decimal::mul($sub,$rate),'100');$subtotal=Decimal::add($subtotal,$sub);$tax=Decimal::add($tax,$taxAmount);$lines[]=['variant'=>$variant,'quantity'=>$qty,'unit_price'=>$price,'tax_rate'=>$rate,'tax_amount'=>$taxAmount,'line_total'=>Decimal::add($sub,$taxAmount)];}$total=Decimal::add($subtotal,$tax);$paid='0';foreach($d['payments'] as $payment)$paid=Decimal::add($paid,Decimal::normalize((string)$payment['amount']));if(Decimal::compare($paid,$total)!==0)throw ValidationException::withMessages(['payments'=>['POS payments must equal the receipt total.']]);$receipt=PosReceipt::create(['tenant_id'=>$t,'company_id'=>$register->company_id,'register_id'=>$register->id,'shift_id'=>$shift->id,'customer_id'=>$d['customer_id']??null,'cashier_id'=>$r->user()->id,'number'=>'POS-'.now()->format('YmdHis').'-'.Str::upper(Str::random(4)),'subtotal'=>$subtotal,'tax_total'=>$tax,'total'=>$total,'idempotency_key'=>$d['idempotency_key']]);foreach($lines as $i=>$line){if(!$register->location_id)throw ValidationException::withMessages(['register'=>['A stock location is required for stock-tracked POS sales.']]);PosReceiptItem::create(['tenant_id'=>$t,'receipt_id'=>$receipt->id,'variant_id'=>$line['variant']->id,'quantity'=>$line['quantity'],'unit_price'=>$line['unit_price'],'tax_rate'=>$line['tax_rate'],'tax_amount'=>$line['tax_amount'],'line_total'=>$line['line_total']]);$movements->post(['tenant_id'=>$t,'variant_id'=>$line['variant']->id,'location_id'=>$register->location_id,'created_by'=>$r->user()->id,'movement_type'=>'pos_sale','quantity'=>Decimal::sub('0',$line['quantity']),'unit_cost'=>$line['variant']->cost??'0','reference_type'=>PosReceipt::class,'reference_id'=>$receipt->id,'idempotency_key'=>'pos:'.$receipt->id.':'.$i]);}foreach($d['payments'] as $payment)PosReceiptPayment::create(['tenant_id'=>$t,'receipt_id'=>$receipt->id,'method'=>$payment['method'],'amount'=>$payment['amount'],'reference'=>$payment['reference']??null,'state'=>'verified']);return $receipt->load(['items','payments']);});event(new \App\Events\PosReceiptPosted($t,$receipt->id,$receipt->company_id,(string)$receipt->total));return response()->json(['data'=>$receipt],201);}
 public function closeShift(Request $r,PosShift $shift,OptionalModuleService $modules,AuthorizationService $auth){$modules->require('pos');$t=app(TenantContext::class)->id();abort_unless($shift->tenant_id===$t,404);$register=$shift->register()->firstOrFail();abort_unless($auth->allows($r->user(),$t,'pos.manage',$register->company_id),403);abort_unless($shift->state==='open',422,'Shift is already closed.');$d=$r->validate(['closing_cash'=>'required|numeric|min:0','closing_notes'=>'nullable|string']);$shift->update([...$d,'state'=>'closed','closed_at'=>now()]);return response()->json(['data'=>$shift->fresh()]);}
}
